import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Card, Typography, Space, Input, InputNumber, Button, Table, Switch, Tag, message, Badge } from 'antd';
import { API_BASE } from '../api';

const { Title, Text } = Typography;

const buildAuthHeaders = (): HeadersInit => {
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  const tgId = sessionStorage.getItem('tg_id');
  if (tgId) headers['X-Telegram-User-ID'] = tgId;
  const token = sessionStorage.getItem('token');
  if (token) headers['Authorization'] = `Bearer ${token}`;
  return headers;
};

const ResilienceAdmin: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [backupEnabled, setBackupEnabled] = useState<boolean>(true);
  const [backupEncrypt, setBackupEncrypt] = useState<boolean>(true);
  const [destInput, setDestInput] = useState('');
  const [destinations, setDestinations] = useState<string[]>(['/var/backups/soulpulse']);

  const [protocolsJson, setProtocolsJson] = useState<string>('[]');
  const [actorName, setActorName] = useState('ResilienceGuardian');
  const [processKey, setProcessKey] = useState('auto_recovery');
  const [seedHost, setSeedHost] = useState('api.telegram.org:443');

  // FW learning policy
  const [fwEnabled, setFwEnabled] = useState<boolean>(true);
  const [fwAuto, setFwAuto] = useState<boolean>(false);
  const [fwSuffix, setFwSuffix] = useState<string>('api.deepseek.com');
  const [fwSuffixes, setFwSuffixes] = useState<string[]>(["api.telegram.org","yandex.ru","google.com","api.deepseek.com","gigachat.devices.sberbank.ai"]);

  // PROD->DEV sync policy
  const [syncEnabled, setSyncEnabled] = useState<boolean>(false);
  const [syncHour, setSyncHour] = useState<number>(4);
  const [syncMinute, setSyncMinute] = useState<number>(0);
  const [syncWarn, setSyncWarn] = useState<number>(15);
  const [syncNotify, setSyncNotify] = useState<number>(468326902);
  const [syncEnvJson, setSyncEnvJson] = useState<string>(JSON.stringify({ PROD_SSH: 'root@217.12.38.238', PROD_PG_URL: 'postgresql://soulpulse:pass@127.0.0.1:5432/soulpulse', DEV_PG_URL: 'postgresql://soulpulse:pass@127.0.0.1:5432/soulpulse_dev' }, null, 2));

  // Incidents tail
  const [incidents, setIncidents] = useState<any[]>([]);
  // Reminders & ACK view
  const [reminders, setReminders] = useState<any[]>([]);
  const [ackMap, setAckMap] = useState<Record<number, boolean>>({});
  const [autoRefresh, setAutoRefresh] = useState<boolean>(true);

  // TimeAdmin (system TZ / now / NTP)
  const [timeSystemTz, setTimeSystemTz] = useState<string>('');
  const [timeNowUtc, setTimeNowUtc] = useState<string>('');
  const [timeNowSystem, setTimeNowSystem] = useState<string>('');
  const [timeNtp, setTimeNtp] = useState<any>(null);
  const [timeTzInput, setTimeTzInput] = useState<string>('');

  const apiFetch = async (path: string, method: string = 'GET', body?: any) => {
    const opts: RequestInit = { method, headers: buildAuthHeaders() };
    if (body !== undefined) opts.body = typeof body === 'string' ? body : JSON.stringify(body);
    const res = await fetch(`${API_BASE}${path}`, opts);
    if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
    return res.json().catch(() => ({}));
  };

  const loadBackupPolicy = async () => {
    try {
      const data = await apiFetch('/admin/resilience/backup/policy');
      setBackupEnabled(!!data.enabled);
      setBackupEncrypt(!!data.encrypt);
      setDestinations(Array.isArray(data.destinations) ? data.destinations : []);
    } catch { message.error('Ошибка загрузки политики бэкапа'); }
  };

  const saveBackupPolicy = async () => {
    try {
      await apiFetch('/admin/resilience/backup/policy', 'PUT', {
        enabled: backupEnabled,
        encrypt: backupEncrypt,
        destinations,
      });
      message.success('Политика бэкапа сохранена');
    } catch { message.error('Не удалось сохранить политику'); }
  };

  const addDestination = () => {
    const v = destInput.trim();
    if (!v) return;
    if (!destinations.includes(v)) setDestinations([...destinations, v]);
    setDestInput('');
  };

  const removeDestination = (d: string) => {
    setDestinations(destinations.filter(x => x !== d));
  };

  const loadProtocols = async () => {
    try {
      const data = await apiFetch('/admin/resilience/knowledge/protocols');
      const items = Array.isArray(data.items) ? data.items : [];
      setProtocolsJson(JSON.stringify(items, null, 2));
    } catch { message.error('Ошибка загрузки протоколов знаний'); }
  };

  const loadFwPolicy = async () => {
    try {
      const data = await apiFetch('/admin/resilience/net/fw/learning_policy');
      setFwEnabled(!!data.enabled);
      setFwAuto(!!data.auto);
      setFwSuffixes(Array.isArray(data.suffixes) ? data.suffixes : []);
    } catch { message.error('Ошибка загрузки FW политики'); }
  };

  const saveFwPolicy = async () => {
    try {
      await apiFetch('/admin/resilience/net/fw/learning_policy', 'PUT', { enabled: fwEnabled, auto: fwAuto, suffixes: fwSuffixes });
      message.success('FW политика сохранена');
    } catch { message.error('Не удалось сохранить FW политику'); }
  };

  const addFwSuffix = () => {
    const v = fwSuffix.trim(); if (!v) return;
    if (!fwSuffixes.includes(v)) setFwSuffixes([...fwSuffixes, v]);
    setFwSuffix('');
  };
  const removeFwSuffix = (s: string) => setFwSuffixes(fwSuffixes.filter(x => x !== s));

  const saveProtocols = async () => {
    try {
      let items: any[] = [];
      try { items = JSON.parse(protocolsJson); } catch { message.warning('Некорректный JSON'); return; }
      await apiFetch('/admin/resilience/knowledge/protocols', 'PUT', { items });
      message.success('Протоколы сохранены');
    } catch { message.error('Не удалось сохранить протоколы'); }
  };

  const registerActor = async () => {
    try {
      await apiFetch('/admin/resilience/knowledge/register_actor', 'POST', { name: actorName.trim() });
      message.success('Актор зарегистрирован');
    } catch { message.error('Не удалось зарегистрировать актора'); }
  };

  const registerProcess = async () => {
    try {
      await apiFetch('/admin/resilience/knowledge/register_process', 'POST', { key: processKey.trim() });
      message.success('Процесс зарегистрирован');
    } catch { message.error('Не удалось зарегистрировать процесс'); }
  };

  const verifyKnowledge = async () => {
    try {
      const data = await apiFetch('/admin/resilience/knowledge/verify', 'POST');
      message.success(`Проверка выполнена, инцидентов: ${data.incidents ?? 0}`);
    } catch { message.error('Не удалось выполнить проверку знаний'); }
  };

  const seedFwSource = async () => {
    try {
      await apiFetch('/admin/resilience/knowledge/seed_source_quant', 'POST', { host: seedHost.trim() });
      message.success('Источник добавлен и квант создан');
    } catch { message.error('Не удалось добавить источник'); }
  };

  const seedAutoInstallerPlan = async () => {
    try {
      await apiFetch('/admin/resilience/knowledge/seed_auto_installer_plan', 'POST', { title: 'Авто‑инсталлятор: чистое восстановление PROD' });
      message.success('Квант плана авто‑инсталлятора создан');
    } catch { message.error('Не удалось создать квант плана'); }
  };

  // Sync policy API
  const loadSyncPolicy = async () => {
    try {
      const data = await apiFetch('/admin/resilience/sync/prod_to_dev');
      setSyncEnabled(!!data.enabled);
      setSyncHour(Number(data.hour ?? 4));
      setSyncMinute(Number(data.minute ?? 0));
      setSyncWarn(Number(data.warn_minutes ?? 15));
      setSyncNotify(Number(data.notify_tg_id ?? 0));
      try { setSyncEnvJson(JSON.stringify(data.env || {}, null, 2)); } catch {}
    } catch { message.error('Ошибка загрузки политики синхронизации'); }
  };

  const saveSyncPolicy = async () => {
    try {
      let envObj: any = {};
      try { envObj = JSON.parse(syncEnvJson); } catch { message.warning('Некорректный JSON в ENV'); return; }
      await apiFetch('/admin/resilience/sync/prod_to_dev', 'PUT', {
        enabled: syncEnabled,
        hour: syncHour,
        minute: syncMinute,
        warn_minutes: syncWarn,
        notify_tg_id: syncNotify,
        env: envObj,
      });
      message.success('Политика синхронизации сохранена');
    } catch { message.error('Не удалось сохранить политику синхронизации'); }
  };

  const runSyncNow = async () => {
    try {
      const res = await apiFetch('/admin/resilience/sync/prod_to_dev/run', 'POST');
      if (res?.ok) message.success('Задача синхронизации поставлена в очередь');
      else message.info('Ответ принят');
    } catch { message.error('Не удалось поставить задачу синхронизации'); }
  };

  const loadIncidents = async () => {
    try {
      const data = await apiFetch('/admin/soul/processor/incidents?limit=50');
      setIncidents(Array.isArray(data.items) ? data.items : []);
    } catch { /* no-op */ }
  };

  const loadReminders = async () => {
    try {
      const data = await apiFetch('/miniapp/reminders?include_sent=true');
      setReminders(Array.isArray(data) ? data : []);
    } catch { /* no-op */ }
  };

  const loadAckIncidents = async () => {
    try {
      const data = await apiFetch('/admin/soul/processor/incidents?limit=200');
      const items: any[] = Array.isArray(data.items) ? data.items : [];
      const map: Record<number, boolean> = {};
      for (const it of items) {
        if (it?.type === 'reminder_ack') {
          const m = /id=(\d+)/.exec(String(it.detail || ''));
          if (m) map[Number(m[1])] = true;
        }
      }
      setAckMap(map);
    } catch { /* no-op */ }
  };

  // TimeAdmin helpers
  const loadTimeStatus = async () => {
    try {
      const data = await apiFetch('/admin/time/status');
      setTimeSystemTz(String(data.system_tz || ''));
      setTimeNowUtc(String((data.now || {}).utc || ''));
      setTimeNowSystem(String((data.now || {}).system || ''));
      setTimeNtp(data.ntp ?? null);
    } catch { message.error('Ошибка загрузки статуса времени'); }
  };
  const loadTimeSettings = async () => {
    try {
      const data = await apiFetch('/admin/time/settings');
      setTimeTzInput(String(data.system_tz || ''));
    } catch { message.error('Ошибка загрузки настроек времени'); }
  };
  const saveTimeSettings = async () => {
    try {
      await apiFetch('/admin/time/settings', 'PUT', { system_tz: (timeTzInput || '').trim() });
      message.success('Системная TZ обновлена');
      await loadTimeStatus();
      await loadTimeSettings();
    } catch { message.error('Не удалось сохранить системную TZ'); }
  };

  useEffect(() => { void loadBackupPolicy(); void loadProtocols(); void loadFwPolicy(); void loadSyncPolicy(); void loadIncidents(); void loadReminders(); void loadAckIncidents(); void loadTimeStatus(); void loadTimeSettings(); }, []);

  useEffect(() => {
    if (!autoRefresh) return;
    const t = setInterval(() => { void loadIncidents(); void loadReminders(); void loadAckIncidents(); }, 10000);
    return () => clearInterval(t);
  }, [autoRefresh]);

  return (
    <div style={{ padding: 'var(--sp-spacing-sm)', boxSizing: 'border-box', maxWidth: '100%' }}>
      <Space align="center" style={{ width: '100%', justifyContent: 'space-between' }}>
        <Title level={3} style={{ marginBottom: 'var(--sp-spacing-sm)' }}>Resilience Admin</Title>
        <Space>
          <Button type="default" onClick={() => navigate('/reminders')}>📋 Напоминания</Button>
        </Space>
      </Space>
      <Space direction="vertical" style={{ width: '100%' }} size="large">
        <Card title="Политика бэкапов">
          <Space direction="vertical" style={{ width: '100%' }} size="middle">
            <Space>
              <Text strong>Включено:</Text>
              <Switch checked={backupEnabled} onChange={setBackupEnabled} />
              <Text strong>Шифрование:</Text>
              <Switch checked={backupEncrypt} onChange={setBackupEncrypt} />
              <Button type="primary" onClick={saveBackupPolicy}>Сохранить</Button>
              <Button onClick={loadBackupPolicy}>Обновить</Button>
            </Space>
            <Space direction="vertical" style={{ width: '100%' }}>
              <Text strong>Назначения хранения</Text>
              <Space>
                <Input placeholder="/var/backups/soulpulse" value={destInput} onChange={(e) => setDestInput(e.target.value)} style={{ width: 360 }} />
                <Button onClick={addDestination}>Добавить</Button>
              </Space>
              <Space wrap>
                {destinations.map(d => (
                  <Tag key={d} closable onClose={() => removeDestination(d)} color="geekblue">{d}</Tag>
                ))}
              </Space>
            </Space>
          </Space>
        </Card>

        <Card title="Протоколы знаний и покрытие">
          <Space direction="vertical" style={{ width: '100%' }} size="middle">
            <Text strong>Список протоколов (JSON)</Text>
            <Input.TextArea value={protocolsJson} onChange={(e) => setProtocolsJson(e.target.value)} rows={10} style={{ fontFamily: 'monospace' }} />
            <Space>
              <Button type="primary" onClick={saveProtocols}>Сохранить протоколы</Button>
              <Button onClick={loadProtocols}>Обновить</Button>
              <Button onClick={verifyKnowledge}>Проверить покрытие</Button>
            </Space>
            <Space>
              <Input placeholder="Имя актора" value={actorName} onChange={(e) => setActorName(e.target.value)} style={{ width: 240 }} />
              <Button onClick={registerActor}>Зарегистрировать актора</Button>
              <Input placeholder="Ключ процесса" value={processKey} onChange={(e) => setProcessKey(e.target.value)} style={{ width: 240 }} />
              <Button onClick={registerProcess}>Зарегистрировать процесс</Button>
            </Space>
          </Space>
        </Card>

        <Card title="FW Allowlist / Посев источников и плана восстановления">
          <Space>
            <Input placeholder="host[:port]" value={seedHost} onChange={(e) => setSeedHost(e.target.value)} style={{ width: 280 }} />
            <Button onClick={seedFwSource}>Добавить источник + Квант</Button>
            <Button onClick={seedAutoInstallerPlan}>Создать Квант плана авто‑инсталлятора</Button>
          </Space>
        </Card>

        <Card title="FW Learning политика">
          <Space direction="vertical" style={{ width: '100%' }} size="middle">
            <Space>
              <Text strong>Обучение включено:</Text>
              <Switch checked={fwEnabled} onChange={setFwEnabled} />
              <Text strong>Авто‑добавление:</Text>
              <Switch checked={fwAuto} onChange={setFwAuto} />
              <Button type="primary" onClick={saveFwPolicy}>Сохранить</Button>
              <Button onClick={loadFwPolicy}>Обновить</Button>
            </Space>
            <Space direction="vertical" style={{ width: '100%' }}>
              <Text strong>Доверенные суффиксы</Text>
              <Space>
                <Input placeholder="example.com" value={fwSuffix} onChange={(e) => setFwSuffix(e.target.value)} style={{ width: 260 }} />
                <Button onClick={addFwSuffix}>Добавить</Button>
              </Space>
              <Space wrap>
                {fwSuffixes.map(s => (<Tag key={s} closable onClose={() => removeFwSuffix(s)} color="purple">{s}</Tag>))}
              </Space>
              <Button onClick={async()=>{ try{ const res = await apiFetch('/admin/resilience/net/fw/learn','POST'); message.success(`Обновлено: ${res.updated??0}`);}catch{message.error('Не удалось выполнить обучение');}}}>Запустить обучение сейчас</Button>
            </Space>
          </Space>
        </Card>

        <Card title="Время (TimeAdmin) — системная TZ и статус">
          <Space direction="vertical" style={{ width: '100%' }} size="middle">
            <Space wrap>
              <Text strong>Системная TZ (текущая):</Text>
              <Tag color="blue">{timeSystemTz || '—'}</Tag>
              <Text strong>Now UTC:</Text>
              <Tag>{timeNowUtc || '—'}</Tag>
              <Text strong>Now System:</Text>
              <Tag>{timeNowSystem || '—'}</Tag>
              <Text strong>NTP:</Text>
              <Tag color={(timeNtp && timeNtp.synced) ? 'green' : 'default'}>{(timeNtp && (timeNtp.synced ? 'synced' : 'unsynced')) || 'n/a'}</Tag>
              <Button onClick={loadTimeStatus}>Обновить статус</Button>
            </Space>
            <Space>
              <Text strong>Установить системную TZ:</Text>
              <Input placeholder="Europe/Moscow" value={timeTzInput} onChange={(e)=>setTimeTzInput(e.target.value)} style={{ width: 240 }} />
              <Button type="primary" onClick={saveTimeSettings}>Сохранить TZ</Button>
              <Button onClick={loadTimeSettings}>Загрузить настройки</Button>
            </Space>
          </Space>
        </Card>

        <Card title="PROD→DEV синхронизация (плановая/ручная)">
          <Space direction="vertical" style={{ width: '100%' }} size="middle">
            <Space wrap>
              <Text strong>Включено:</Text>
              <Switch checked={syncEnabled} onChange={setSyncEnabled} />
              <Text strong>Час (UTC):</Text>
              <InputNumber min={0} max={23} value={syncHour} onChange={(v)=>setSyncHour(Number(v||0))} />
              <Text strong>Минута:</Text>
              <InputNumber min={0} max={59} value={syncMinute} onChange={(v)=>setSyncMinute(Number(v||0))} />
              <Text strong>Warn (мин):</Text>
              <InputNumber min={0} max={120} value={syncWarn} onChange={(v)=>setSyncWarn(Number(v||0))} />
              <Text strong>Notify TG:</Text>
              <InputNumber min={0} value={syncNotify} onChange={(v)=>setSyncNotify(Number(v||0))} />
              <Button type="primary" onClick={saveSyncPolicy}>Сохранить</Button>
              <Button onClick={loadSyncPolicy}>Обновить</Button>
              <Button onClick={runSyncNow}>Запустить сейчас</Button>
            </Space>
            <Text strong>ENV (JSON)</Text>
            <Input.TextArea rows={6} style={{ fontFamily: 'monospace' }} value={syncEnvJson} onChange={(e)=>setSyncEnvJson(e.target.value)} />
          </Space>
        </Card>

        <Card title="Последние инциденты процессора (50)">
          <Table
            rowKey={(r:any)=>r.id || `${r.type}-${r.created_at}`}
            dataSource={incidents}
            pagination={{ pageSize: 10 }}
            size="small"
            columns={[
              { title: 'Тип', dataIndex: 'type', width: 180 },
              { title: 'Детали', dataIndex: 'detail' },
              { title: 'Когда', dataIndex: 'created_at', width: 200 },
            ] as any}
          />
          <Button onClick={loadIncidents} style={{ marginTop: 8 }}>Обновить</Button>
        </Card>

        <Card title="Статусы напоминаний (sent/ack)">
          <Space style={{ marginBottom: 8 }}>
            <Switch checked={autoRefresh} onChange={setAutoRefresh} />
            <Text>Автообновление</Text>
            <Button onClick={() => { void loadReminders(); void loadAckIncidents(); }}>Обновить</Button>
          </Space>
          <Table
            rowKey={(r:any)=>r.id}
            dataSource={reminders}
            pagination={{ pageSize: 10 }}
            size="small"
            columns={[
              { title: 'ID', dataIndex: 'id', width: 80 },
              { title: 'Заголовок', dataIndex: 'title' },
              { title: 'Дата', dataIndex: 'reminder_date', width: 200 },
              { title: 'Sent', dataIndex: 'is_sent', width: 100, render: (v:boolean)=> v ? <Tag color="green">sent</Tag> : <Tag color="volcano">pending</Tag> },
              { title: 'ACK', key: 'ack', width: 100, render: (_:any, r:any)=> ackMap[r.id] ? <Badge status="success" text="ack" /> : <Badge status="default" text="no" /> },
            ] as any}
          />
        </Card>
      </Space>
    </div>
  );
};

export default ResilienceAdmin;


